+            Model.InsuranceProvider,
+            Model.Doctor ?? "",
+            Model.TimeSlot ?? "");
+
+        if (!result.IsValid)
+        {
+            serverErrors = new Dictionary<string, string>(result.FieldErrors);
+            availabilityChecked = false;
+        }
+        else
+        {
+            availabilityChecked = true;
+        }
+    }
